insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('rotating', 'advanced', 'module', 'm01-a-stage-is-not-a-pump', 1, 'The SOKU K-2101 stage runs at a polytropic efficiency of 0.755000, and its exponent ratio is 0.293761435 while the same function at an efficiency of one returns 0.221789883. What is the quotient of those two figures?', '["0.957006239, which is the quotient of the two heads the same stage returns.", "1.324503311, which is one over the polytropic efficiency.", "1.285000, which is k for the 0.648000 gravity gas being compressed.", "0.722539710, which is the isentropic efficiency the stage reports."]'::jsonb, 1, 'A real compression is irreversible, the irreversibility shows up as heat in the gas, and the exponent of the real path is steeper than the reversible one by exactly the factor the efficiency sets.'),
  ('rotating', 'advanced', 'module', 'm01-a-stage-is-not-a-pump', 2, 'SOKU leaves at 294.4000 psia and 333.5954 degF. Run the identical stage through the isentropic exponent instead and the answer is 269.8918 degF. What is the size of that difference and why does it matter?', '["63.7036 degF, and a design that sized coolers and chose valve material off the reversible figure would be short by that much.", "63.7036 degF, which is the amount the stated discharge limit of 300.0000 degF would have to be raised by before the warning clears.", "There is no difference at all, because the exponent sets the head and the discharge temperature follows the ratio alone.", "63.7036 degF, and it is the rise the interstage cooler has to take out before the second stage picks the gas up."]'::jsonb, 0, 'Both figures are the same stage asked through two exponents. The polytropic one carries the efficiency and the isentropic one does not, so the reversible path predicts a cooler machine than the one being built.'),
  ('rotating', 'advanced', 'module', 'm01-a-stage-is-not-a-pump', 3, 'Compressibility on the SOKU stage is 0.987732307 at suction and 0.988949105 at discharge, a difference of 0.001216798. Why does the engine average them?', '["The suction value cannot be read until the discharge temperature is known, so the average is the only figure available when the head is computed.", "Averaging hides the difference of 0.001216798, which would otherwise split the two horsepower routes.", "The DAK fit is written in averaged reduced coordinates, so a single-end z sits outside it.", "The head integral runs along the whole path, so one value of z has to stand in for every state between the two ends."]'::jsonb, 3, 'The mean of the two endpoints is the ordinary engineering choice. It is a good one here because the two ends are close, and it would be a weaker one on a stage whose ends are far apart.'),
  ('rotating', 'advanced', 'module', 'm01-a-stage-is-not-a-pump', 4, 'The chain on a compressor stage runs exponent, discharge state, the z at that state, the average, and only then the head. What breaks if a calculation fixes z first and works forward?', '["It loses the suction value of 0.987732307, which is the only one of the two ends the engine reports.", "It produces a head in the wrong units, since z carries the conversion from ft lbf per lbm to Btu per hr.", "It has assumed the answer it was about to compute, because the discharge z cannot be read until the discharge temperature is known.", "It makes the two horsepower routes disagree, which is the check that would otherwise have caught it."]'::jsonb, 2, 'The discharge temperature came out of the exponent, the discharge z comes out of that temperature, and the average comes out of both ends. Order is what makes the 0.988340706 on this stage mean anything.'),
  ('rotating', 'advanced', 'module', 'm01-a-stage-is-not-a-pump', 5, 'SOKU returns a polytropic head of 63604.9582 ft lbf per lbm and an isentropic head of 60870.3418, with a polytropic efficiency of 0.755000000 and an isentropic efficiency of 0.722539710. Which efficiency divides which head?', '["Each head is divided by the efficiency of its own path, so the polytropic pair go together and the isentropic pair go together.", "The larger head is divided by the larger efficiency in both cases, which on this stage happens to pair 63604.9582 with 0.722539710.", "Both heads are divided by the polytropic efficiency, since that is the one the machine actually has and the isentropic figure is a reference.", "The isentropic head is divided by the mechanical efficiency of 0.968000 and the polytropic head by the polytropic efficiency."]'::jsonb, 0, 'Each pair is a complete statement of the same machine and the two statements give the same power. Crossing the pairs produces a figure that still looks like a compressor, which is why it survives review.'),
  ('rotating', 'advanced', 'module', 'm01-a-stage-is-not-a-pump', 6, 'Gas horsepower by the polytropic route is 2279.6019 and by the isentropic route is 2279.6019, a difference of -9.094947017729282e-13 hp. What does that agreement establish?', '["That the averaged z of 0.988340706 was taken at the right two states.", "That the isentropic efficiency of 0.722539710 was derived and not typed.", "That neither head was transcribed wrong, since a typo would open a gap.", "Nothing about either head, because the two routes are one expression written two ways."]'::jsonb, 3, 'The exponent ratio times the polytropic efficiency is the isentropic exponent ratio exactly, so dividing either head by its own efficiency is the same expression. It holds for every input, including a wrong one.'),
  ('rotating', 'advanced', 'module', 'm01-a-stage-is-not-a-pump', 7, 'On the identity table the last column runs -2.7755575615628914e-17, -2.7755575615628914e-17, 2.7755575615628914e-17 and 5.551115123125783e-17. What is that column?', '["A derived tolerance, which the engine gate uses as the band the two horsepower routes are allowed to differ by.", "A subtraction done on each row, and the residual it shows is the size of double-precision rounding.", "The gap between the polytropic and the isentropic head on each of the four gas and efficiency pairs.", "The residual left by the least-squares solve behind the fit."]'::jsonb, 1, 'The exponent ratio times the polytropic efficiency is compared with the isentropic exponent ratio on each of the four rows. A residual at that magnitude is arithmetic and it is not a disagreement.'),
  ('rotating', 'advanced', 'module', 'm01-a-stage-is-not-a-pump', 8, 'The engine gate that compares the two horsepower routes is kept and labelled as a shape property. What is the check that CAN fail beside it?', '["A comparison of the polytropic head against the published golden for the same case, which is the only route in the package that does not share the derivation.", "A sweep of k from 1.200000 to 1.400000 checking that the head and the power both rise, which fails if either the exponent or the efficiency is transcribed wrong.", "A numerical quadrature of the integral of v dp along the polytropic path, with a negative control that moves the exponent and must break the comparison.", "A bisection on the stage ratio until the warning turns on, which brackets the answer independently of the head expression."]'::jsonb, 2, 'The question to ask of any gate is what input would make it fail. The control is the load-bearing half, because a comparison nobody has ever seen fail is a comparison nobody has ever tested.'),
  ('rotating', 'advanced', 'module', 'm01-a-stage-is-not-a-pump', 9, 'The same SOKU stage is asked against stated discharge limits of 200.0000, 250.0000, 300.0000 and 400.0000 degF. What happens to the discharge temperature across those four probes?', '["It falls as the stated limit falls, because the engine trims the ratio to stay inside whatever limit the caller states.", "It is 333.5954 degF on every one of them.", "It is 333.5954 degF on the first three and 269.8918 degF on the fourth, where no warning is raised.", "It is reported only on the row at 400.0000 degF, since the other three return a warning in place of a temperature."]'::jsonb, 1, 'The limit is a limit and it is not an input to the thermodynamics. Three of the four rows carry a warning and the row at 400.0000 degF carries none, and the temperature never moves.'),
  ('rotating', 'advanced', 'module', 'm01-a-stage-is-not-a-pump', 10, 'With no discharge limit stated, the warning turns on between a ratio of 2.7616873004480746 and 2.761687300448075, where the discharge temperatures are 299.99999999999994 and 300.00000000000006 degF. What has that bisection established, and what is its standing?', '["The ratio at which the valves and the lube oil become the binding constraint, which the engine treats as a machine limit.", "The width of the bracket the bisection closed on.", "The highest ratio one stage may take before staging begins.", "The default the engine applies when a caller states none, and it is held for literature."]'::jsonb, 3, 'The figure is customary and no publication in this repository stands behind it, so nothing graded in this course rests on it. State a limit rather than inheriting one.'),
  ('rotating', 'advanced', 'module', 'm01-a-stage-is-not-a-pump', 11, 'Walk the polytropic efficiency across the SOKU stage and the head runs 65574.3395 ft lbf per lbm at 0.650000 and 62157.4133 at 0.860000, while the gas power runs 2729.8297 hp and 1955.7326. Why does a worse machine show a larger head?', '["A lower efficiency steepens the path, so the stage has more head to deliver and it delivers that head less efficiently.", "A lower efficiency raises the discharge temperature, and the averaged z rises with it by enough to carry the difference.", "The head is what the driver supplies, so the mechanical losses are inside it.", "A lower efficiency cuts the mass flow, so the head per pound rises."]'::jsonb, 0, 'Read the table as two effects at once. The power carries both of them and the head carries only the first, which is why the power falls faster across that walk than the head does.'),
  ('rotating', 'advanced', 'module', 'm01-a-stage-is-not-a-pump', 12, 'Held at the SOKU conditions and walked across k, the exponent ratio runs 0.220750552 at 1.200000, 0.289735099 at 1.280000 and 0.378429518 at 1.400000. What decides which of those rows a machine sits on?', '["The polytropic efficiency, since the exponent ratio is the isentropic one divided by it and k is recovered from the pair.", "The pressure ratio the stage is asked to take, because a steeper path is what a larger ratio produces.", "What the user types for k, because it is a property of the fluid and it is a stated input here.", "The suction state, since the DAK correlation returns k along with the compressibility at that reduced pressure and temperature."]'::jsonb, 2, 'A higher k gives a steeper path. The machine contributes the efficiency and the stream contributes k, so a stage report that quotes an exponent without saying which efficiency produced it cannot be checked by anybody.'),
  ('rotating', 'advanced', 'module', 'm01-a-stage-is-not-a-pump', 13, 'Across the ratio sweep the warning is null at 1.500000, 2.000000 and 2.500000 and set at 3.000000, 3.500000, 4.000000 and 4.500000. What else is happening down that table?', '["The ratio per stage is falling as the count the engine would choose rises, which is why the warning appears part way down.", "The discharge pressure, the temperature, the head and the power are all rising together.", "The head rises while the power falls, because a larger ratio moves more of the work into the gas and less into the shaft.", "The compressibility average falls toward the ideal-gas limit, which is what turns the warning on at 3.000000."]'::jsonb, 1, 'The row at 2.500000 reaches 278.1057 degF and the row at 3.000000 reaches 318.6976 degF, so the stated limit is crossed between them and the warning appears from the fourth row on.'),
  ('rotating', 'advanced', 'module', 'm01-a-stage-is-not-a-pump', 14, 'The SOKU stage returns 2279.6019 gas horsepower and 2354.9606 brake horsepower at a mechanical efficiency of 0.968000. Which figure sizes the driver, and what sits between them?', '["The brake figure, and what sits between them is the gearbox, the bearings and the seals of the machine itself.", "The gas figure, and what sits between them is the driver efficiency, which is applied again when the fuel is worked out.", "The brake figure, and what sits between them is the interstage cooling duty the train has to reject.", "Either figure, since at a mechanical efficiency of 0.968000 the two are inside the tolerance any driver is quoted to."]'::jsonb, 0, 'Gas horsepower is what the gas receives and brake horsepower is what the coupling has to deliver. A driver sized on the gas figure is short by the mechanical losses of the machine.'),
  ('rotating', 'advanced', 'module', 'm01-a-stage-is-not-a-pump', 15, 'The SOKU suction comes back with the note "Ppr 0.137 against 0.2 at 92 psia and 104 F is below the 0.2 where the DAK fit data start; the z-factor here runs toward the ideal-gas limit". Is that a complaint?', '["Yes. A state below the reduced pressure the fit data start at is an extrapolation, and the engine records it so the z of 0.987732307 can be discounted.", "No, because the note is raised on the discharge rather than the suction, and the discharge sits inside the fit data on this stage.", "No. The surface runs to the ideal-gas limit as the reduced pressure goes to zero, so a low-pressure suction is an ordinary machine.", "Yes, and it is the reason the stage averages the two ends rather than carrying the suction value through."]'::jsonb, 2, 'The engine says where in the correlation the state sits instead of leaving a reader to wonder whether a quiet return meant the state was never checked at all.'),
  ('rotating', 'advanced', 'module', 'm02-the-stage-count-and-the-limit-that-governs', 1, 'SOKU as a whole duty moves 26.000000 MMscfd from 92.000000 psia to 985.000000 psia at 104.0000 degF. What is the overall ratio, and what is the ratio each stage ends up taking?', '["An overall ratio of 10.706521739, split into a ratio per stage of 3.200000.", "An overall ratio of 2.204023061, which the three stages each take in full.", "An overall ratio of 10.706521739, split into a ratio per stage of 2.204023061.", "An overall ratio of 10.706521739, which the per-stage limit of 4.000000 then caps."]'::jsonb, 2, 'The count comes first and the ratio per stage follows from it. Equal ratios are the split the engine applies, so the per-stage figure is one number on the return rather than a list.'),
  ('rotating', 'advanced', 'module', 'm02-the-stage-count-and-the-limit-that-governs', 2, 'On SOKU the ratio rule demands 2 stages and the temperature limit demands 3. What does the engine return?', '["3, and it names discharge temperature as what governed.", "3, with the governing rule left unreported because the two demands disagree.", "2, because a ratio limit of 4.000000 was stated by the caller and the temperature limit was a default.", "The mean of the two demands rounded upward, which on this duty is also 3."]'::jsonb, 0, 'The returned count is the larger of the two demands on every row of the sweep, and the governed-by field names which demand it came from.'),
  ('rotating', 'advanced', 'module', 'm02-the-stage-count-and-the-limit-that-governs', 3, 'A trial stage count has to be tested from some inlet temperature. What inlet does the engine use?', '["The suction for every trial, since the suction is the only temperature the duty states.", "The cooled temperature for every trial, because the count is about the stages after the first.", "The mean of the suction and the cooled temperature, weighted by how many stages the trial has.", "The suction for one stage, and the hotter of the suction and the cooled temperature for more than one."]'::jsonb, 3, 'A single stage starts from the suction and is never cooled, because there is nothing after it to cool for. Every stage after the first starts from the interstage cooler.'),
  ('rotating', 'advanced', 'module', 'm02-the-stage-count-and-the-limit-that-governs', 4, 'SOKU cools back to 110.0000 degF against a suction of 104.0000 degF. Which figure was the three-stage trial tested from, and why?', '["104.0000 degF, because the count is a property of the duty and the duty states its suction.", "110.0000 degF, because it is the hotter of the two and it is what the second and third stages actually see.", "110.0000 degF, because the engine always prefers the cooled temperature once a trial has more than one stage.", "104.0000 degF, since the first stage is the hottest on this train and a count is tested against the hottest stage."]'::jsonb, 1, 'Test a three-stage trial from the suction when the stages will run warmer and you have evaluated a machine that is not the one being built.'),
  ('rotating', 'advanced', 'module', 'm02-the-stage-count-and-the-limit-that-governs', 5, 'Across the nine rows of the discharge-pressure sweep, how often does the engine answer "both equally", and what does that row mean?', '["On 3 of the 9 rows, and it means neither rule could be evaluated because the inlet was ambiguous.", "On 5 of the 9 rows, and it means the engine declined to choose between two counts that differ by one.", "On 3 of the 9 rows, and it means the count sits on the edge of both rules at once.", "On 1 of the 9 rows, and it means both demands gave the same ratio per stage."]'::jsonb, 2, 'Where the two demands are equal the engine says so rather than picking one. A small move in either input changes the answer there, so it is the least comfortable row on the table.'),
  ('rotating', 'advanced', 'module', 'm02-the-stage-count-and-the-limit-that-governs', 6, 'At a discharge of 300.000000 psia the sweep shows an overall ratio of 3.260869565, a demand of 1 by ratio and 2 by temperature. What is returned?', '["2 stages, governed by discharge temperature.", "1 stage, because the ratio rule is evaluated first and a single stage is inside the stated limit.", "2 stages, governed by both equally, since one demand is the other less one.", "1 stage, with a warning that the temperature limit would have asked for a second."]'::jsonb, 0, 'The larger demand wins on every row. The ratio rule set a floor of one machine and the temperature limit set the answer at two.'),
  ('rotating', 'advanced', 'module', 'm02-the-stage-count-and-the-limit-that-governs', 7, 'The ratio-per-stage column climbs from 2.056367445 to 2.204023061 to 2.353953103 and then drops to 2.131775386. What is happening at the drop?', '["The ratio limit of 4.000000 has been reached, so the engine has begun trimming the per-stage ratio.", "A machine has been added, so each stage is taking a smaller bite of the same job.", "The intercooler approach has risen above the suction, which lowers the ratio each stage can take.", "The overall ratio has fallen, because the discharge pressure step from 1500.000000 to 1900.000000 psia is smaller than the previous one."]'::jsonb, 1, 'The count climbs in steps and the ratio per stage records the same steps from the other side. Each stage takes less because there is one more of them.'),
  ('rotating', 'advanced', 'module', 'm02-the-stage-count-and-the-limit-that-governs', 8, 'Brake horsepower climbs smoothly down the sweep while the stage count climbs in steps. Why is that worth saying out loud?', '["Because the power column is the only one on the table that is derived rather than returned by the engine.", "Because a smooth power curve means the stage count is not affecting the work, so the extra machines are free.", "Because the steps in the count are what make the brake horsepower column non-monotonic between 1500.000000 and 1900.000000 psia.", "Because every step is a machine, a cooler and a foundation, and the power column gives no hint that one is about to happen."]'::jsonb, 3, 'Those are two different kinds of quantity and they cost money in two different ways. Moving from 1500.000000 psia to 1900.000000 psia adds the fourth machine.'),
  ('rotating', 'advanced', 'module', 'm02-the-stage-count-and-the-limit-that-governs', 9, 'The sweep carries a column derived as the stated limit of 300.0000 degF less the hottest stage. How many of its nine rows come out negative?', '["3 of the 9, on the rows where the engine reports both equally.", "2 of the 9, at the highest discharge pressures on the table.", "0 of the 9.", "9 of the 9, because the approach of 110.0000 degF sits above the suction."]'::jsonb, 2, 'A negative entry there would be a train running over the limit it was staged against. The column is non-negative on every row, on a duty whose approach sits above its suction.'),
  ('rotating', 'advanced', 'module', 'm02-the-stage-count-and-the-limit-that-governs', 10, 'The temperature-driven search runs over a fixed range of trial counts. What is that range and what happens past it?', '["One stage to twelve, and past twelve it refuses rather than returning the best trial it had.", "One stage to twelve, and past twelve it returns the twelfth trial with a warning attached to it instead.", "Two stages to twelve, since a single stage is settled by the ratio rule alone and needs no trial.", "One stage upward with no bound, ending when the discharge falls under the limit."]'::jsonb, 0, 'Without a cap a duty whose limit cannot be met at any count would either run forever or hand back whatever the last trial produced, and the second of those looks like an answer.'),
  ('rotating', 'advanced', 'module', 'm02-the-stage-count-and-the-limit-that-governs', 11, 'The refusal at the cap reads: "no practical stage count keeps the discharge temperature under the limit: 12 equal stages still reach 318.0 F against a stated limit of 110.0 F, from an inlet of 100.0 F". What does that sentence contain?', '["The count it gave up at and the overall ratio it was working on, with the temperatures held back on the returned object.", "A recommendation to raise the stated limit, followed by the three figures that recommendation is based on.", "The count it gave up at and the ratio per stage that count implies, which together fix the discharge it reached.", "The count it gave up at, the temperature the best trial reached, the limit it was measured against and the inlet it was measured from."]'::jsonb, 3, 'Nothing in that message requires the reader to re-run anything to understand what went wrong, which is the whole standard a refusal is held to here.'),
  ('rotating', 'advanced', 'module', 'm02-the-stage-count-and-the-limit-that-governs', 12, 'The cap is almost never what a user meets, because cheaper explanations are caught at the door first. What does a duty need before it can reach the cap at all?', '["An overall ratio above 1000.000000000 and a stated discharge limit that the caller has left to the default.", "A discharge limit above the suction temperature, a readable efficiency, a workable ratio limit, and an overall ratio large enough that twelve equal stages are still too hot.", "A polytropic efficiency of zero, since that is the only input the stage-count search does not guard.", "An intercooler approach below the suction temperature, which is what makes twelve equal stages the coolest arrangement available."]'::jsonb, 1, 'A limit at or below the suction is refused by name as impossible, so it cannot reach the cap. Only the combination of all four gets through.'),
  ('rotating', 'advanced', 'module', 'm02-the-stage-count-and-the-limit-that-governs', 13, 'Beside its message the stage-count refusal carries its measurements. What are they on the probe that reaches the cap?', '["Stage counts tried 12, coolest discharge 318.0 degF, limit 110.0000 degF and a ratio per stage of 2.204023061.", "Stage counts tried 12 and an overall ratio of 10.706521739, with the temperatures carried only inside the message.", "Stage counts tried 12, coolest discharge 317.9889 degF, limit 110.0000 degF, inlet 100.0000 degF, overall ratio 1000.000000000.", "Stage counts tried 1000.000000000, coolest discharge 317.9889 degF and an inlet of 104.0000 degF."]'::jsonb, 2, 'Each one answers a question a reader would otherwise have to re-run the engine to answer. The string is the headline and the numbers are the evidence.'),
  ('rotating', 'advanced', 'module', 'm02-the-stage-count-and-the-limit-that-governs', 14, 'The coolest discharge twelve equal stages could reach is 317.9889 degF against a stated limit of 110.0000 degF. What does the subtraction between them tell a reader?', '["That the gap cannot be read from those two figures without the inlet of 100.0000 degF as well.", "That the gap is 207.9889 degF, which is far too wide for cooling to be the lever.", "That the gap is 207.9889 degF, which the approach has to fall by.", "That the gap is 317.9889 degF, the figure the limit is taken from."]'::jsonb, 1, 'A gap of a few degrees would say a colder cooler or a slightly higher limit closes it. A gap this wide says the fault is the limit or the pressure.'),
  ('rotating', 'advanced', 'module', 'm02-the-stage-count-and-the-limit-that-governs', 15, 'A stage count of 3 tells an engineer what to buy. What does the governing rule tell them?', '["What to argue about, because it names which of the two inputs is the lever and which is slack.", "How the count would change if the gas or the rate moved, since the governing rule is what carries them.", "Which stage on the train will be the hottest, which is where the discharge limit is judged against.", "Whether the count came from the search or from the closed form."]'::jsonb, 0, 'If the temperature limit governed, a colder cooler or a higher stated limit is the lever and the ratio limit is slack. Pulling the slack lever changes nothing and costs a revision.'),
  ('rotating', 'advanced', 'module', 'm03-the-train-and-what-buys-the-stages', 1, 'Every stage of the SOKU train shows a ratio of 2.204023061. What is that column telling a reader?', '["That the three stages were sized independently and happened to land together.", "The equal-ratio rule showing up as a fact about the machine that was built.", "That the ratio limit of 4.000000 was binding, which forces the stages into equality.", "That the cooler brought every stage back to one inlet, which is what equalises the ratios."]'::jsonb, 1, 'The engine is not choosing a split. It applies the equal-ratio rule and reports the one number it produces, and the train then runs on it.'),
  ('rotating', 'advanced', 'module', 'm03-the-train-and-what-buys-the-stages', 2, 'Down the SOKU train the polytropic head falls from 40786.5845 to 40678.7794 to 39563.3251 ft lbf per lbm while every stage takes the same ratio. What accounts for the fall?', '["The compressibility average falls from 0.987885118 to 0.974896675 to 0.948163998 as the pressure level rises, and the same ratio on a less ideal gas is less work per pound.", "The inlet temperature falls along the train, because each cooler reaches a little further than the one before it.", "The mass flow falls along the train as fuel is drawn off for the driver at each stage.", "The polytropic efficiency is applied once per stage, so the third stage carries it three times over."]'::jsonb, 0, 'The gas horsepower falls with the head, from 1461.7913 to 1457.9276 to 1417.9497, and the third stage is the cheapest of the three despite doing the same ratio as the other two.'),
  ('rotating', 'advanced', 'module', 'm03-the-train-and-what-buys-the-stages', 3, 'Stages two and three of the SOKU train both go in at 110.0000 degF and both come out at 258.8635 degF. Why are they identical while stage one is not?', '["They share one cooler, so the second cooling duty of 4386630.5362 Btu per hr is the figure that covers both of them together.", "Their compressibility averages are equal, which fixes the head and the discharge together.", "The third stage is not cooled at all, so the engine carries the second stage figures straight forward rather than recomputing them.", "They start from the same cooled temperature and take the same ratio, and stage one starts from the 104.0000 degF suction."]'::jsonb, 3, 'Stage one is the odd one out on this table. The other two are the same calculation on a different pressure level, which is why their inlets and their discharges match exactly.'),
  ('rotating', 'advanced', 'module', 'm03-the-train-and-what-buys-the-stages', 4, 'What does the SOKU train total, and what is the final discharge?', '["Gas 4481.0626 hp, brake 4337.6686 hp, cooling 8.5503 Btu per hr, and a final discharge of 251.2956 degF on the last stage.", "Gas 1461.7913 hp and brake 1510.1150 hp per stage, with a final discharge of 300.0000 degF.", "Gas 4337.6686 hp, brake 4481.0626 hp, cooling 8550254.4381 Btu per hr, and a final discharge of 258.8635 degF.", "Gas 4337.6686 hp, brake 4481.0626 hp, no cooling total, and a final discharge of 110.0000 degF."]'::jsonb, 2, 'The cooling total is 8.5503 MMBtu per hr, and reading it beside the brake horsepower is what makes a train result an equipment list rather than a single number.'),
  ('rotating', 'advanced', 'module', 'm03-the-train-and-what-buys-the-stages', 5, 'The stated discharge limit on the SOKU train is 300.0000 degF. Which temperature is the limit judged against, and how much room is left?', '["The hottest stage, which is 258.8635 degF here, leaving 41.1365 degF.", "The final discharge, which on a train with more than one stage is always the hottest.", "The mean of the three stage discharges, which is what the return reports as the train temperature.", "The inlet the count was tested at, since that is where the limit was applied when the count was chosen."]'::jsonb, 0, 'The hottest stage is derived as the maximum of the out column. On this train the hottest and the last happen to be the same stage, and quoting the final discharge as the train temperature is the habit that goes wrong elsewhere.'),
  ('rotating', 'advanced', 'module', 'm03-the-train-and-what-buys-the-stages', 6, 'The third stage of the SOKU train reports a cooling duty of 0.0000 Btu per hr and a cooled-to temperature of null. Is that a defect?', '["No, but only because this train has three stages. On a two-stage train the engine reports a cooling duty on both rows.", "Yes. The aftercooler duty belongs on that row and the engine has left it out.", "Yes. A null there hides the fact that the gas leaves that stage at 258.8635 degF rather than at the 110.0000 degF the others reach.", "No. Interstage cooling brings a gas down before the next stage picks it up, and after the last stage there is none."]'::jsonb, 3, 'A zero in the cooled-to column would have claimed the gas was chilled to zero degrees Fahrenheit. The engine declines to name a temperature that does not exist.'),
  ('rotating', 'advanced', 'module', 'm03-the-train-and-what-buys-the-stages', 7, 'The first SOKU cooler takes 4163623.9019 Btu per hr and the second takes 4386630.5362. Both cool to 110.0000 degF, so why do they differ?', '["The second cooler is working on a denser gas, because it sits at a higher pressure level on the train.", "The second stage leaves at 258.8635 degF and the first leaves at 251.2956 degF, so the second cooler has further to bring the gas back.", "The first cooler takes a share of the aftercooler duty, which the engine subtracts from its row.", "The two duties are quoted at different reference temperatures, one at the suction and one at the approach."]'::jsonb, 1, 'Each of those figures sizes an air cooler or a shell-and-tube exchanger, and each carries a plot area, a fan or cooling water demand, and a pressure drop the next stage pays for.'),
  ('rotating', 'advanced', 'module', 'm03-the-train-and-what-buys-the-stages', 8, 'Walk the SOKU intercooler approach upward with everything else held. What happens to the stage count?', '["It holds at 3 through 150.0000 degF and rises to 4 at 180.0000 degF.", "It stays at 3 the whole way, and what rises instead is the hottest stage temperature.", "It holds at 3 through 130.0000 degF, rises to 4 at 150.0000 degF and to 5 at 180.0000 degF.", "It falls from 5 to 3 as the approach rises, because a warmer inlet needs less pressure ratio per stage."]'::jsonb, 2, 'Nothing about the gas, the rate or the two pressures changed across that walk. What changed is the temperature every stage after the first starts from.'),
  ('rotating', 'advanced', 'module', 'm03-the-train-and-what-buys-the-stages', 9, 'On the approach walk the second column reads 104.0000 degF on the first three rows and then follows the approach. What is that column?', '["The inlet the count was tested at, and it is the only thing on the table that says which machine the count was bought for.", "The temperature the first stage leaves at, which is fixed while the approach sits below the suction.", "The approach itself, reported again so the two halves of the comparison can be read on one line.", "The coldest inlet any stage on the train receives, which is the suction until the approach passes it."]'::jsonb, 0, 'The rule is the suction for one stage and the hotter of the suction and the cooled temperature for more. On every row it is the inlet the stages after the first actually run from.'),
  ('rotating', 'advanced', 'module', 'm03-the-train-and-what-buys-the-stages', 10, 'While the approach sits at or below 104.0000 degF the count and the train read the same inlet whichever rule is used. What does that force about how the walk is done?', '["It has to stop at the suction, since above it the two halves are asking different questions.", "It has to be repeated at a second stated limit, since one limit cannot discriminate the two rules.", "It has to be done at a single approach, since the rule is identical either side of the suction.", "It has to cross the suction, because only the warmer rows could ever have come apart."]'::jsonb, 3, 'A comparison only ever run where it cannot fail proves nothing. Across the whole walk 0 stages sit over the stated limit and 0 carry a warning, and the last four rows are the ones where the answer was in doubt.'),
  ('rotating', 'advanced', 'module', 'm03-the-train-and-what-buys-the-stages', 11, 'On the three coldest rows of the approach walk the hottest stage is 251.2956 degF and it does not move. Why not?', '["The engine caps the reported hottest stage at the first stage value until the approach passes the suction.", "Stage one runs from the suction whatever the cooler does, and on those rows it is the hottest stage on the train.", "All three of those rows share a stage count of 3, and the hottest stage is fixed by the count rather than by the inlets.", "The ratio per stage is unchanged on those rows, and the hottest stage depends only on the ratio."]'::jsonb, 1, 'What moves on those rows is every stage after the first, running 233.6372, then 246.2503, then 251.2956 degF as the approach climbs to meet the suction.'),
  ('rotating', 'advanced', 'module', 'm03-the-train-and-what-buys-the-stages', 12, 'Take the same gas from 92.000000 psia to 420.000000 psia at 104.0000 degF with a stated discharge limit of 230.0000 degF and an approach of 165.0000 degF. What does the engine return?', '["5 stages governed by the ratio limit, with the hottest stage at 230.0000 degF and no room left.", "4 stages governed by discharge temperature, with one stage over the stated limit and carrying a warning.", "5 stages governed by discharge temperature, a hottest stage of 223.2904 degF and 6.7096 degF of room.", "A refusal, because an approach of 165.0000 degF sits above the stated limit the stages are measured against."]'::jsonb, 2, 'The approach is 61.0000 degF above the suction, and the count is the price of that. The return says discharge temperature governed and the discharge is under the limit it was governed by.'),
  ('rotating', 'advanced', 'module', 'm03-the-train-and-what-buys-the-stages', 13, 'On that 420.000000 psia case the stage discharges are 156.5982, 223.2904, 223.2904, 223.2904 and 223.2904 degF. What is the gap between the first and the rest, and what causes it?', '["66.6921 degF, because the first stage runs from the suction and every later stage runs from the 165.0000 degF approach at the same ratio.", "66.6921 degF, because the first stage takes a smaller ratio than the four that follow it.", "6.7096 degF, which is the room the hottest stage leaves under the stated limit of 230.0000 degF.", "66.6921 degF, because the first stage is the only one whose compressibility is evaluated at both ends."]'::jsonb, 0, 'That gap between stage one and the rest is the approach being paid for, and what it bought was the count. 0 of the 5 stages sit over the limit or carry a warning.'),
  ('rotating', 'advanced', 'module', 'm03-the-train-and-what-buys-the-stages', 14, 'Across the five rows of the cooling table that share a stage count of 3, what happens as the approach warms?', '["The cooling rises from 8.1149 to 8.9856 MMBtu per hr while the gas power falls the other way from 4453.3383 to 4220.8083 hp.", "The cooling falls from 8.9856 to 8.1149 MMBtu per hr and the gas power rises from 4220.8083 to 4453.3383 hp.", "Both the cooling and the gas power fall together, since a warmer inlet at the same ratio is a lighter duty on each of them.", "The cooling holds at 8.5503 MMBtu per hr while only the gas power moves."]'::jsonb, 1, 'A colder gas entering each stage is denser, the same pressure ratio costs less work on it, and the heat taken out to make it colder is the exchanger''s problem instead of the driver''s.'),
  ('rotating', 'advanced', 'module', 'm03-the-train-and-what-buys-the-stages', 15, 'Where the fourth machine appears the cooling goes from 8.1149 to 8.6374 MMBtu per hr while the gas power goes from 4453.3383 to 4447.6481 hp. Why do both move against the trade?', '["The fourth cooler is added without a fourth stage, so its duty appears with no work against it.", "The approach at that row passes the stated discharge limit, which forces the engine to cool harder than it was asked to.", "The extra machine changed the ratio each stage takes, so the comparison is between two different trains.", "The gas power is reported per stage from that row on, so it falls while the total still rises."]'::jsonb, 2, 'The trade is a statement about a fixed stage count. Written with the count attached it survives the whole table, and written without it the sixth row contradicts it.'),
  ('rotating', 'advanced', 'module', 'm04-the-machine-the-driver-and-the-fuel', 1, 'Hold the rate, the gas and the temperature and move only the suction pressure. The inlet volume runs 9555.2490 acfm at 30.000000 psia and 204.9510 acfm at 1200.000000 psia. What is the same on every row?', '["The density of the gas at the flange, since the rate, the gas and the temperature are all held.", "The compressibility, since z is evaluated once at the standard base rather than at each suction.", "The molar flow, which is what a rate in MMscfd actually is.", "The brake horsepower, because the screen is asked at a fixed power and only the casing size moves."]'::jsonb, 2, 'A rate in MMscfd is a molar quantity dressed as a volume, measured at a standard pressure and temperature no part of the plant is at. Raise the pressure and the same moles occupy less space, which is the density rising and the volume falling.'),
  ('rotating', 'advanced', 'module', 'm04-the-machine-the-driver-and-the-fuel', 2, 'What three quantities does the actual inlet volume at a suction state depend on?', '["The absolute pressure, the absolute temperature and the compressibility at that state.", "The absolute pressure, the specific gravity and the overall ratio the duty asks for.", "The absolute temperature, the compressibility and the polytropic efficiency of the machine.", "The absolute pressure, the mass flow and the molecular weight of the gas being moved."]'::jsonb, 0, 'At the SOKU suction of 92.000000 psia the volume is 3090.0016 acfm. The engine evaluates z at the suction rather than assuming it, which is why a bad suction state is refused before a volume is produced.'),
  ('rotating', 'advanced', 'module', 'm04-the-machine-the-driver-and-the-fuel', 3, 'A small high-pressure gathering duty at 14.6564 acfm, an overall ratio of 3.000000 and 180.0000 brake hp is screened. What comes back, and on what first reason?', '["Reciprocating, on the reason that an overall ratio of 3.000000 is more than a wheel takes in one bite.", "Reciprocating, on the reason that only 14.7 acfm at suction is too small for a centrifugal wheel to be efficient.", "Either, on the reason that at 180.0000 brake hp both machine types are viable and other criteria decide.", "Centrifugal, on the reason that a duty this small is a packaged machine and a wheel is the cheaper package."]'::jsonb, 1, 'The branch is decided on the inlet volume first and on the ratio second. A second reason follows, that under 200 bhp a packaged gas-engine recip is the usual answer.'),
  ('rotating', 'advanced', 'module', 'm04-the-machine-the-driver-and-the-fuel', 4, 'Two of the four screened duties reach the same word. The deep booster sits at 2015.0151 acfm and takes a ratio of 11.500000, and it is also called reciprocating. Which road did it take there?', '["It is chosen on brake power, because 2100.0000 brake hp is inside the band where a recip is the usual package.", "It is chosen on size as well, since 2015.0151 acfm is below the volume where a wheel becomes efficient.", "It is chosen on the compressibility at its suction, which the screen reads before it reads the volume.", "It is chosen on ratio rather than on size, because recips take ratio far more happily than centrifugals."]'::jsonb, 3, 'That is the argument for reading the reason line. A recip chosen for size becomes a wheel if the duty grows, and a recip chosen for ratio does not.'),
  ('rotating', 'advanced', 'module', 'm04-the-machine-the-driver-and-the-fuel', 5, 'Four duties are put through the screen. What do their returns show about recommendations and reasons?', '["There are 4 distinct first reasons and fewer distinct recommendations, because two duties reach reciprocating by different roads.", "There are 4 distinct recommendations and 4 distinct first reasons, one of each per duty.", "There are 4 distinct recommendations and 2 distinct first reasons, since the reasons pair up by machine type.", "There are 2 distinct first reasons and 4 distinct recommendations, since the reason line repeats where the verdict does not."]'::jsonb, 0, 'A recommendation on its own does not say what would change it. The reason line is the only thing that says which road a duty took to the branch it reached.'),
  ('rotating', 'advanced', 'module', 'm04-the-machine-the-driver-and-the-fuel', 6, 'The fourth branch of the screen is the word "either", and 7962.6965 acfm at 5000.0000 brake hp is what reaches it. What is such a return worth?', '["It is a placeholder for a branch the screen has not been given thresholds for yet.", "It is a refusal in a softer shape, and a caller should treat it as a recommendation that is missing.", "It is a real answer, and its reason line hands the decision back with the criteria attached.", "It is the branch the screen falls back to whenever the inlet volume sits between two of its thresholds."]'::jsonb, 2, 'The reason line says the decision goes on availability, footprint, maintenance philosophy and driver. A screen that always named a machine would be pretending to a resolution it does not have.'),
  ('rotating', 'advanced', 'module', 'm04-the-machine-the-driver-and-the-fuel', 7, 'The thresholds the screen turns on are 500 and 5000 and 20000 acfm, ratios of 4 and 6, and 200 and 10000 brake hp. What is their standing in this course?', '["They are measured out of the engine by bisection, so they are treated as derived constants.", "They are published thresholds this repository carries, so a recommendation can be graded against them.", "They are defaults a caller may override, so they are graded only where the caller states them.", "They are held for literature, so no graded value anywhere in the course is a recommendation."]'::jsonb, 3, 'They are customary and unsourced here. Each held item is used, each is printed, and none of them decides a graded answer.'),
  ('rotating', 'advanced', 'module', 'm04-the-machine-the-driver-and-the-fuel', 8, 'The screen asks for the compressibility at the suction before it asks for the volume. Why is a finiteness test on the volume not enough?', '["A finiteness test would accept an Infinity, which is what a suction at exactly absolute zero returns.", "A negative number is finite, and a suction below absolute zero produces a negative volume.", "The volume is computed from the compressibility, so a finiteness test on it can only repeat the z check.", "A finiteness test cannot see the ratio, and the branch is decided on the ratio before the volume."]'::jsonb, 1, 'A screen that only asked whether the answer was finite would take that negative volume, find it below about 500 acfm and recommend a reciprocating machine on it.'),
  ('rotating', 'advanced', 'module', 'm04-the-machine-the-driver-and-the-fuel', 9, 'Three suction states are refused at the screen. Which refusal''s MESSAGE names a reduced pressure?', '["The one at 1000.000000 psia and -150.0000 degF, where Tpr 0.848 sits below the validity range.", "The one at 24000.000000 psia and 100.0000 degF, where Ppr 35.814 sits above the DAK validity limit of 30.", "The one at 200 psia and -600 F, where the z-factor needs a temperature above absolute zero.", "All three, since the screen reports both reduced coordinates on every refusal it makes."]'::jsonb, 1, 'The colder probe''s message names Tpr 0.848 against 1.0, and the state below absolute zero is refused before any reduced coordinate can be formed at all. Both of the in-window refusals carry their reduced pair on the returned object; only one of them says a reduced pressure out loud.'),
  ('rotating', 'advanced', 'module', 'm04-the-machine-the-driver-and-the-fuel', 10, 'The SOKU driver runs at a heat rate of 8100.000000 Btu per hp hr on a fuel gas of 985.000000 Btu per scf. What does it burn, and at what thermal efficiency?', '["36296606.9250 Btu per hr, which is 3.401478 MMscfd, at 31.412760 percent.", "8550254.4381 Btu per hr, or 0.884384331 MMscfd, at 41.039251 percent.", "36296606.9250 Btu per hr, or 0.884384331 MMscfd, at a thermal efficiency of 23.131214 percent.", "36296606.9250 Btu per hr, which is 0.884384331 MMscfd, at 31.412760 percent."]'::jsonb, 3, 'Btu per hour is what the driver needs and MMscfd is what the field loses. The second figure is the one a commercial reader can act on.'),
  ('rotating', 'advanced', 'module', 'm04-the-machine-the-driver-and-the-fuel', 11, 'The SOKU station compresses 26.000000 MMscfd and its driver burns 0.884384331 MMscfd. What is that as a share, and how is it derived?', '["3.401478 percent, the fuel over the throughput times 100.", "3.401478 percent, the fuel over the brake horsepower of 4481.0626 times 100.", "0.884384331 percent, which is the fuel figure read directly as a percentage of the stream.", "31.412760 percent, which is the thermal efficiency and is the same quantity stated differently."]'::jsonb, 0, 'Part of what arrives is consumed making the rest of it move, and that part is gas the field does not sell. On a field where the gas has a contract price it is directly a revenue number.'),
  ('rotating', 'advanced', 'module', 'm04-the-machine-the-driver-and-the-fuel', 12, 'Walk the driver heat rate from 6200.000000 to 11000.000000 Btu per hp hr. What happens to the fuel, the thermal efficiency and the share of throughput?', '["All three of them rise, with the share going from 2.603601 to 4.619291 percent as the efficiency climbs with it.", "The fuel rises and both the efficiency and the share fall, since a worse driver moves less of the stream than a good one.", "The fuel and the share rise while the efficiency falls, taking the share from 2.603601 to 4.619291 percent.", "The fuel and the efficiency both fall while only the share rises, from 2.603601 to 4.619291 percent."]'::jsonb, 2, 'At 6200.000000 Btu per hp hr the fuel is 0.676936155 MMscfd at 41.039251 percent, and at 11000.000000 it is 1.201015758 MMscfd at 23.131214 percent.'),
  ('rotating', 'advanced', 'module', 'm04-the-machine-the-driver-and-the-fuel', 13, 'The driver calculation refuses a heat rate of 2000 Btu per hp hr. What sets that boundary, and how was it confirmed?', '["It is a threshold with a safety factor on it, chosen so a plausible datasheet is never rejected by accident.", "It is the quotient of the fuel heating value of 985.000000 Btu per scf and the heat rate, checked against the published golden cases.", "It is the 33000.000000 ft lbf per minute that a horsepower is, converted to Btu per hour inside the units module.", "It is the 2544.433577644024 Btu that one horsepower-hour is, read out of the thermal efficiency and again by halving until the refusal turns on, with the two routes differing by 0."]'::jsonb, 3, 'A driver delivering one horsepower-hour of shaft work on less fuel heat than that would be creating energy. The refusal boundary IS the constant rather than a policy laid over it.'),
  ('rotating', 'advanced', 'module', 'm04-the-machine-the-driver-and-the-fuel', 14, 'The universal gas constant measured out of the polytropic head is 1545.350400 ft lbf per lbmol degR, and the gas properties module exports the same value once multiplied by 144. What do the two figures do?', '["They give a quotient of 1.324503311, which is the factor the polytropic efficiency contributes.", "They give a quotient of 1.000000000000000 and a difference of 2.2737367544323206e-13.", "They differ by 144, which is the square inches per square foot the export has to be scaled by.", "They cannot be compared, because the head route reports in ft lbf per lbm and the export in psia ft3."]'::jsonb, 1, 'One value of one constant, in two modules where one imports from the other. A package holding two opinions could not say which of them any answer carries, however small the gap.'),
  ('rotating', 'advanced', 'module', 'm04-the-machine-the-driver-and-the-fuel', 15, 'The mass-flow route in this module gives 379.483571856287 standard cubic feet per lbmol and the inlet-volume route reveals a standard pressure over temperature of 0.028279485058 psia per degR. What is shown by putting them together?', '["That the two routes reach the same quotient with a difference of 0, so the module has one standard base.", "That the volume route uses a base 144 times the mass route''s, which is the square inches per square foot.", "That the two bases differ by 2.2737367544323206e-13, which is the same residual the gas constant shows.", "That the standard pressure and the standard temperature can each be recovered separately from the volume route."]'::jsonb, 0, 'That quotient is all the volume route reveals about its base from outside, and the two figures cannot be separated from it. The same MMscfd is one molar quantity whether it becomes a mass flow or an inlet volume.'),
  ('rotating', 'advanced', 'module', 'm05-what-a-refusal-is', 1, 'A caller hands one of these two modules an input it cannot work with. What shape does the answer take?', '["A thrown exception carrying the name of the input, which the caller is expected to catch.", "An ordinary returned object carrying an error string that names the input that is actually wrong.", "A returned object whose numeric fields are set to NaN, with the error text in a warning field.", "A returned object with the offending field removed, so a caller reading it finds nothing there."]'::jsonb, 1, 'Neither module throws. A caller checks a property rather than catching, which is a deliberate shape and it has a consequence the next question is about.'),
  ('rotating', 'advanced', 'module', 'm05-what-a-refusal-is', 2, 'The property check is the only check most callers ever make. What follows from that?', '["A guard can be omitted where the value is always finite, since the check would never fire.", "Errors have to be raised at construction rather than at the call, because a call has no return to carry them.", "The error string has to be generic, because a caller comparing strings cannot rely on a specific wording.", "A non-finite value slipped past it is worse than having no guard at all."]'::jsonb, 3, 'A caller that sees no error believes it has a number. That is why both modules were worked through input by input: every fault in this module reached a caller with no error key on it before the guard beside it was written.'),
  ('rotating', 'advanced', 'module', 'm05-what-a-refusal-is', 3, 'A motor efficiency above one, a negative motor efficiency and a motor efficiency of zero all come back with the same sentence. Is that a defect?', '["No. Those are three typing mistakes against one rule, and the message states the rule.", "Yes. Three distinct faults should carry three distinct messages, as the compression module now does.", "No, because the pump module prints the typed value beside each sentence.", "Yes, a negative and an above-one efficiency need opposite fixes."]'::jsonb, 0, 'The refusal reads that motor efficiency must be greater than 0 and at most 1. Where two typed values reach one guard from opposite directions and the correction differs, the compression module does carry the value.'),
  ('rotating', 'advanced', 'module', 'm05-what-a-refusal-is', 4, 'A system curve built with no static head is refused at construction. Why is the guard finiteness rather than positivity?', '["Because a positivity test would also refuse a static head of zero.", "Because the curve object cannot be inspected until it is called, so only finiteness is available at construction.", "A static head may legitimately be negative, because the destination can sit below the pump.", "Because the friction head at a stated flow already carries the sign, so the static head is taken as a magnitude."]'::jsonb, 2, 'That one is the sharpest of the set: a curve object can look healthy and carry a correct coefficient while the function hanging off it is unusable. The message says the head may be negative but it cannot be missing.'),
  ('rotating', 'advanced', 'module', 'm05-what-a-refusal-is', 5, 'A speed ratio of one hundred is handed to the affinity laws. What comes back?', '["A refusal naming the speed ratio, because the affinity laws stop describing a real machine there.", "A full result of 100000 gpm, 3000000 ft and 100000000 brake hp, with a warning attached.", "A result with the flow and head filled in and the brake power returned as NaN, since the power leg is the cube.", "A result with every field set to the value at the present speed, and a warning that the change was declined."]'::jsonb, 1, 'The warning says the power leg goes as the cube, so this is an extrapolation on the number that sizes the driver. It is a warning rather than an error, and the numbers do come back.'),
  ('rotating', 'advanced', 'module', 'm05-what-a-refusal-is', 6, 'A log of one of these returns shows null where a number belongs. What has it failed to tell you?', '["Which of a NaN and an Infinity came back, because neither has a spelling in JSON.", "Whether the field was computed at all, since a refused field is removed rather than nulled.", "Which input the refusal named, because the error string is dropped by an ordinary serialiser.", "Whether the value was refused or rounded to zero by the printer."]'::jsonb, 0, 'The two mean different things. A NaN says an input could not be read and an Infinity says something was divided by zero, so probing these modules needs a serialiser that prints what was really returned.'),
  ('rotating', 'advanced', 'module', 'm05-what-a-refusal-is', 7, 'Five exports in these two modules return a plain number. Which five?', '["pumps.headFtToPsi, pumps.psiToHeadFt, compression.polytropicExponentRatio, compression.compressorTrain and compression.actualInletCfm.", "pumps.headFtToPsi, pumps.psiToHeadFt, compression.stageCount, compression.dischargeTempR and compression.actualInletCfm.", "pumps.psiToHeadFt, compression.polytropicExponentRatio, compression.dischargeTempR, compression.actualInletCfm and compression.stageCount.", "pumps.headFtToPsi, pumps.psiToHeadFt, compression.polytropicExponentRatio, compression.dischargeTempR and compression.actualInletCfm."]'::jsonb, 3, 'Each is a small conversion and each returns a scalar. A plain number has nowhere to put an error key, so those five hold a written contract instead.'),
  ('rotating', 'advanced', 'module', 'm05-what-a-refusal-is', 8, 'What are the three clauses of the contract those five hold?', '["Zero when the inputs cannot be read, never a NaN, and never a negative number.", "NaN when the inputs cannot be read, an Infinity on a division by zero, and never a negative number.", "NaN when the inputs cannot be read, never an Infinity, and never a plausible number.", "NaN when the inputs cannot be read, a documented default otherwise, and never a value outside its own range."]'::jsonb, 2, 'NaN propagates through arithmetic rather than hiding. An Infinity looks like a very large answer and survives a finiteness test in the wrong direction, and a plausible number is the one failure a reader cannot catch.'),
  ('rotating', 'advanced', 'module', 'm05-what-a-refusal-is', 9, 'The bare-number table carries two rows marked as controls, one returning 271.7647058823529 and one returning 1069.0552909632156. What are they for?', '["They show the same functions returning a real number when they can, which is what makes the refusing rows mean anything.", "They fix the two scales the contract is stated at, so a reader can tell a NaN from a rounded zero.", "They are the values the two functions return in place of a NaN when a caller supplies a default.", "They are the published golden cases for those two functions, which is why they are the only rows with numbers."]'::jsonb, 0, 'A contract that says NaN is worth nothing on its own, because a function returning NaN for every input would satisfy it perfectly and compute nothing. It is the same discipline as a negative control on a gate.'),
  ('rotating', 'advanced', 'module', 'm05-what-a-refusal-is', 10, 'compression.actualInletCfm appears on three rows of that table. What do the three show together?', '["One reason to decline and two readable states, which bracket the window the function works inside.", "Two distinct reasons to decline and one reason to answer, all demonstrated rather than asserted.", "Three reasons to decline, since the control row is a state the function also refuses.", "Two reasons to decline and one warning, since a low reduced pressure is noted rather than refused."]'::jsonb, 1, 'It refuses a suction below absolute zero, refuses a state outside the compressibility window, and returns 1069.0552909632156 on a readable state.'),
  ('rotating', 'advanced', 'module', 'm05-what-a-refusal-is', 11, 'Two of the four compression refusals quote the value the caller typed. Which two, and why those?', '["The two temperature messages, because a reader cannot tell degF from degR without the value.", "The efficiency message and the suction temperature message, because both are read from the same input object.", "The polytropic efficiency messages, because a 0 and a 1.5 reach one guard from opposite directions.", "The ratio limit messages, because the same fault arrives through two different functions."]'::jsonb, 2, 'A 0 is probably an empty field or a missing default and a 1.5 is probably a percentage typed where a fraction belonged. A reader told only the rule has to work out which of them they made.'),
  ('rotating', 'advanced', 'module', 'm05-what-a-refusal-is', 12, 'A stated discharge limit sits at or below the suction temperature. The refusal says compression raises the temperature of a gas, so no stage count can meet this limit. What does that clause do?', '["It names the twelve-stage cap as the reason, which is the guard the call would otherwise have reached.", "It reports the inlet the count was tested at, so the approach can be fixed.", "It converts the limit to Rankine, the only form the comparison holds in.", "It forecloses adding stages, which is the obvious fix and can never work here."]'::jsonb, 3, 'Even a stage of vanishing ratio leaves the gas at least as hot as it arrived. The message saves the afternoon that would have gone on intercooling harder.'),
  ('rotating', 'advanced', 'module', 'm05-what-a-refusal-is', 13, 'A per-stage ratio limit of one is asked through the stage-count function and again through the whole-train function. What comes back?', '["A refusal from the stage-count function and a train of one stage from the train function.", "The same refusal, naming the ratio limit, from both entry points.", "Two refusals with the same meaning in different words, one per function.", "A refusal naming the rate and the suction pressure, which are the inputs the train function reads first."]'::jsonb, 1, 'The rate, the suction pressure, the gas gravity and k in that call are all good. A user cannot be told two different stories about one input depending on which tab they were on.'),
  ('rotating', 'advanced', 'module', 'm05-what-a-refusal-is', 14, 'Three suction states are probed against the compressibility window and the solver reports converged on all three. What does that flag establish?', '["Nothing about validity, because a solver converges on the correlation it was given wherever it is asked.", "That the two refused states were refused on their reduced coordinates rather than on the arithmetic.", "That the control row at 600.000000 psia is the only one whose z of 0.919606033 can be trusted.", "That the window of 1.0 to 3.0 and 30 was applied after the solve rather than before it."]'::jsonb, 0, 'It cannot know the fit was never fitted to data out there. Convergence is about the arithmetic and validity is about the data behind it, and reading that flag would have caught neither probe.'),
  ('rotating', 'advanced', 'module', 'm05-what-a-refusal-is', 15, 'Eight things in this course are held for literature. Which is the load-bearing one, and what does the engine do instead of modelling it?', '["The compressibility window, which the engine reports rather than enforces, leaving the caller to judge it.", "The published golden cases, which the engine recomputes at fifty digits rather than comparing against.", "The impeller trim shortfall model, whose power leg is left as the ideal cube while the engine returns the efficiency its own answer implies.", "The 300 degF default discharge limit, which the engine replaces with the hottest stage it measured."]'::jsonb, 2, 'That model has no publication in this repository, so a second unsourced model was not invented to sit beside it. Each held item is used, each is printed, and none decides a graded answer.'),
  ('rotating', 'advanced', 'module', 'm06-the-expert-reading', 1, 'How many published cases does this course carry, and against how many exported functions?', '["16 published cases against the 22 exported functions of the two modules.", "22 published cases against the 16 exported functions of the two modules.", "16 published cases against the 14 exported functions of the pump module alone.", "10 published cases against the 22 exported functions of the two modules."]'::jsonb, 0, 'The pump goldens carry 10 cases in five blocks and the compression goldens 6 cases in two. Both counts are read off the files themselves.'),
  ('rotating', 'advanced', 'module', 'm06-the-expert-reading', 2, 'One published staging case runs from 200.000000 psia to 600.000000 psia at 110.0000 degF with k of 1.250000. What is unusual about its answer?', '["It comes back as a single stage with no governing rule, since a one-stage answer has nothing to compare.", "It comes back governed by the ratio limit, which is the only published case where the ratio rule wins alone.", "It comes back as a single stage, and the engine still names a governing rule, which is both equally.", "It comes back with a ratio per stage above its overall ratio."]'::jsonb, 2, 'The ratio per stage on that case is 3.000000000, which is the whole job in one bite. Where the two demands are equal the engine says so rather than picking one.'),
  ('rotating', 'advanced', 'module', 'm06-the-expert-reading', 3, 'Two other published staging cases return 3 stages at a ratio per stage of 2.154434690 and 4 stages at 2.213363839. What governed each?', '["The ratio limit governed the three-stage case and discharge temperature the four-stage one.", "Discharge temperature governed the three-stage case and both equally the four-stage one.", "Both equally governed the three-stage case and the ratio limit the four-stage one.", "Discharge temperature governed both."]'::jsonb, 3, 'The first runs 100.000000 to 1000.000000 psia at 100.0000 degF and the second 50.000000 to 1200.000000 psia at 90.0000 degF. The temperature limit is the usual binding rule on these duties.'),
  ('rotating', 'advanced', 'module', 'm06-the-expert-reading', 4, 'A published stage case takes 20.000000 MMscfd through a ratio of 3.160000 with k of 1.280000 at an efficiency of 0.750000. What does the engine return against the file?', '["A head of 61985.4682, a discharge of 397.5060 degF, 1725.5940 gas hp and a z average of 0.993426696.", "A head of 61985.4682, a discharge of 323.1720 degF, 1725.5940 gas hp and a z average of 0.986868979.", "A head of 43087.9193, a discharge of 266.2663 degF, 3105.2431 gas hp and a z average of 0.956986144.", "A head of 84758.5707, a discharge of 323.1720 degF, 567.2037 gas hp and a z average of 0.986868979."]'::jsonb, 1, 'Those four fields are the readable ones quoted for each published stage case, and the file carries more besides them.'),
  ('rotating', 'advanced', 'module', 'm06-the-expert-reading', 5, 'Of the three published stage cases, one takes 5.000000 MMscfd through a ratio of 4.000000 and another 50.000000 MMscfd through 2.500000. The first returns the larger head and the smaller gas power. How?', '["The larger head comes from the higher k of 1.300000, and the smaller power comes from the lower efficiency of 0.720000.", "The two are quoted at different z averages, 0.993426696 against 0.956986144, which is what reverses the ordering.", "Head is work per pound and power is that head carried by the mass, so the higher ratio gives the first the larger head and the ten times larger rate gives the second the larger power.", "The smaller rate is a single stage and the larger one is a train, so only the second figure carries every stage."]'::jsonb, 2, 'The first returns a head of 84758.5707 with 567.2037 gas hp and the second a head of 43087.9193 with 3105.2431 gas hp.'),
  ('rotating', 'advanced', 'module', 'm06-the-expert-reading', 6, 'Every published field is compared against the engine on every case rather than sampled. What does that comparison show?', '["That 2 of the 5 fields come back bit for bit and 3 do not, and neither answer is a failure.", "That 5 of the 5 fields come back bit for bit, which is why the gate can be written without a tolerance.", "That 3 of the 5 fields come back bit for bit and 2 do not, the exceptions being the two mass fields.", "That none of the 5 fields comes back bit for bit, because the file and the engine carry different precisions."]'::jsonb, 0, 'The two that agree exactly are massLbHr and zAvg. The file is written by a Python oracle carrying fifty digits and the engine is double precision.'),
  ('rotating', 'advanced', 'module', 'm06-the-expert-reading', 7, 'Which published stage field carries the worst relative gap against the engine, and how large is it?', '["gasHp, at 1.0639229984758982e-12.", "tDischargeF, at 1.522776943887805e-11.", "headPolyFtLbfLbm, at 3.107080181448693e-14.", "zAvg, at 1.522776943887805e-11."]'::jsonb, 1, 'On a field where the two routes take different arithmetic they land a little apart, and that gap is the size of the disagreement rather than the size of an error.'),
  ('rotating', 'advanced', 'module', 'm06-the-expert-reading', 8, 'A gate written against one of those goldens therefore has to carry a tolerance. Where should the tolerance come from?', '["From the precision the digest prints that field at, so the gate and the course agree.", "From the worst gap on the whole table, applied to every field so one number covers them all.", "From the tolerance the published file declares beside each case it carries.", "From the size of the disagreement the two routes really have."]'::jsonb, 3, 'Demanding equality on that table would fail on arithmetic rather than on error, and a tolerance chosen because it looks tidy is a tolerance chosen against nothing.'),
  ('rotating', 'advanced', 'module', 'm06-the-expert-reading', 9, 'There is a second end to that choice, and it is the one worth thinking about. What is it?', '["A tolerance loose enough to swallow a mis-transcribed constant catches nothing at all, so the useful question is what error it is still small enough to see.", "A tolerance tight enough to see a mis-transcribed constant will also fail on rounding, so the two ends cannot both be had.", "A tolerance has to be widened each time the oracle''s precision rises, since the gap moves with it.", "A tolerance stated in relative terms behaves differently on a field near zero, which is why zAvg is compared absolutely."]'::jsonb, 0, 'The two ends are the same question asked twice. Too tight and the gate fails on arithmetic, too loose and it stops being able to see the thing it was written for.'),
  ('rotating', 'advanced', 'module', 'm06-the-expert-reading', 10, 'What is the standing of all 16 published cases in this course?', '["They are the graded truth for the compression half, since the compression goldens agree bit for bit.", "They are held only where the engine and the file disagree, and gradeable where the two match exactly.", "They are held for literature, because every one of them was written by an oracle.", "They are vendor performance runs, which is why the gate against them carries a tolerance."]'::jsonb, 2, 'There is no measured pump test, no vendor performance run and no field compressor datasheet anywhere in this course.'),
  ('rotating', 'advanced', 'module', 'm06-the-expert-reading', 11, 'A figure is held for literature. What does that mean in practice?', '["It is computed but suppressed, so a learner never meets it and no answer can rest on it.", "It is used, it is printed, its gap in provenance is stated with it, and no graded answer rests on it.", "It is quoted from a publication that this repository carries, so any answer that rests on it is already checkable.", "It is frozen at its present value until somebody reads a source against it, so the engine will not recompute it."]'::jsonb, 1, 'Held does not mean wrong and it does not mean ignore. It means no conclusion is allowed to rest on it until somebody reads a source against it.'),
  ('rotating', 'advanced', 'module', 'm06-the-expert-reading', 12, 'The impeller trim shortfall model is held because the engine calls it a published shortfall and names no publication. What did the engine do about its power leg?', '["Removed it, so a trim return carries a flow and a head and no power at all.", "Applied the shortfall to it whole, exactly as it does to the head, since the power leg is the one that sizes a driver.", "Replaced it with the affinity speed law for the power leg, which is exact and needs no publication behind it at all.", "Left it as the ideal cube, and reported the efficiency its own answer implies rather than modelling a second one."]'::jsonb, 3, 'A second unsourced model was not invented to sit beside the first. The affinity speed band is held on the same footing, as a sanity bound rather than a correlation limit.'),
  ('rotating', 'advanced', 'module', 'm06-the-expert-reading', 13, 'The 300 degF discharge limit is one of the eight held items. What exactly is held about it?', '["The whole comparison, so no hot-stage warning is ever raised.", "The value only above 300 degF, since below it the figure is measurable out of the engine.", "The default itself, which is the figure the engine uses when a caller states none.", "The bisection that measured it, since a bracket is evidence about the search and not about the figure."]'::jsonb, 2, 'The warning is measured against whatever the caller does state, and three of the four stated-limit probes raise one. The default is customary and nothing graded rests on it.'),
  ('rotating', 'advanced', 'module', 'm06-the-expert-reading', 14, 'Four subjects are absent from these engines altogether. Which set is it?', '["Surge and its controls, seal and bearing calculations, machine curves and wheel selection, and a required-NPSH-against-flow curve.", "Interstage cooling duties, driver fuel, machine screening and the compressibility window.", "Viscosity correction, operating regions, the affinity laws and parallel operation.", "The polytropic exponent, the stage count search, the twelve-stage cap and the train totals."]'::jsonb, 0, 'Naming a seam is more useful than producing a number from a correlation the package does not have. A surge margin quoted from memory reads exactly like a computed one.'),
  ('rotating', 'advanced', 'module', 'm06-the-expert-reading', 15, 'Given those absences, what does this course actually answer?', '["The machine type to buy, the wheel to select and the surge margin to design the recycle valve for.", "The duty a vendor should be quoting against, the power and the stage count to expect, the suction margin a selection has to survive, and the reasons behind all four.", "The vendor curve at the duty flow, the required NPSH at that flow, and the bearing life that follows.", "The valve dynamics and rod loading a reciprocating machine will see once the stage count is fixed."]'::jsonb, 1, 'The reasons are the part that survives a change of inputs. A number with no reason attached cannot be argued about at a design review.'),
  ('rotating', 'advanced', 'final', null, 1, 'On the identity table the pair k of 1.400000 and an efficiency of 0.820000 gives an exponent ratio of 0.348432056. Multiplied by that efficiency it gives 0.2857142857142857 against an isentropic exponent ratio of 0.28571428571428564. What is being demonstrated?', '["That the product drifts from the isentropic figure as k rises, which is why the table stops at 1.400000.", "That the product is the isentropic exponent ratio exactly, to within double-precision rounding.", "That the efficiency has to be applied twice, once to the exponent and once to the head.", "That a richer gas needs a larger residual, which the last column of the table records."]'::jsonb, 1, 'Because that relation holds for every pair, dividing the isentropic head by the isentropic efficiency and dividing the polytropic head by the polytropic efficiency are one expression.'),
  ('rotating', 'advanced', 'final', null, 2, 'Walk the polytropic efficiency upward across one stage and the exponent ratio runs 0.341215205 at 0.650000 and 0.257895213 at 0.860000. What is a better machine doing to the path?', '["Steepening it, because a better machine delivers more head for the same ratio.", "Leaving it alone, because the exponent is a property of the gas and the efficiency enters later.", "Reversing it, because above an efficiency of 0.755000 the isentropic exponent becomes the larger.", "Flattening it, because less of the work is being turned into heat in the gas."]'::jsonb, 3, 'The discharge follows the exponent, falling from 378.6113 degF at 0.650000 to 301.1829 degF at 0.860000 on that same walk.'),
  ('rotating', 'advanced', 'final', null, 3, 'A stage asked for a ratio of only 1.500000 leaves 92.000000 psia at 138.0000 psia and 175.3008 degF. What are its head and its gas power?', '["19739.9969 ft lbf per lbm and 707.4815 hp.", "35245.9460 ft lbf per lbm and 1263.2148 hp.", "19739.9969 ft lbf per lbm and 2279.6019 hp.", "48215.9853 ft lbf per lbm and 1728.0611 hp."]'::jsonb, 0, 'That row carries a null warning. The discharge pressure, the temperature, the head and the power all rise together as the ratio the stage is asked to take rises.'),
  ('rotating', 'advanced', 'final', null, 4, 'One stage returns a polytropic efficiency of 0.755000000 and an isentropic efficiency of 0.722539710. What is the relationship, and by how much?', '["The polytropic figure is the lower of the two, by 0.032460290.", "They are two names for one quantity and the small gap is rounding.", "The isentropic figure is the lower of the two, by 0.032460290.", "The isentropic figure is the lower of the two, by 0.957006239."]'::jsonb, 2, 'The isentropic head of 60870.3418 ft lbf per lbm is also the smaller of the two heads, so each member of the isentropic pair is smaller than its polytropic counterpart.'),
  ('rotating', 'advanced', 'final', null, 5, 'A reviewer is handed any gate at all and wants to know whether it is worth anything. What is the single question to ask?', '["What tolerance it carries and how that tolerance was chosen.", "What input would make it fail.", "Whether it runs on the published cases or on cases the wave generated.", "Whether it compares two routes or one route against a stored value."]'::jsonb, 1, 'If there is no such input, the gate is a restatement of the formula rather than a test of it, and the confidence it produces is manufactured.'),
  ('rotating', 'advanced', 'final', null, 6, 'A stage at 92.000000 psia is asked for a ratio of 3.200000. What is its discharge pressure, and is that figure a result or an input?', '["294.4000 psia, and it is an input the caller states beside the ratio.", "985.000000 psia, which is the discharge the whole duty is working toward.", "202.7701 psia, which is where the first stage of the train lands.", "294.4000 psia, and it follows from the suction and the ratio."]'::jsonb, 3, 'The pressure ratio and the suction fix the discharge pressure. Everything thermodynamic then follows from the exponent applied at that ratio.'),
  ('rotating', 'advanced', 'final', null, 7, 'Held at one set of conditions and walked across k, the discharge runs 269.0103 degF at 1.200000 and 415.6938 degF at 1.400000. What does that say about where k comes from?', '["The gas analysis, since nothing in the engine measures k and the caller supplies it.", "The suction state, since the correlation returns k along with the compressibility there.", "The polytropic efficiency, since the exponent ratio is the isentropic one divided by it.", "The standard base the module carries, so every duty in this package sits on one row."]'::jsonb, 0, 'Nothing in the engine measures it. A handbook value for a gas the stream is not will produce an exponent, a temperature and a power that are all internally consistent and all wrong.'),
  ('rotating', 'advanced', 'final', null, 8, 'One row of the sweep has both rules asking for the same thing, 2 stages, at an overall ratio of 4.891304348. What goes into the governed-by field there?', '["The ratio limit, because it is the rule evaluated first.", "Discharge temperature, because it is the rule that governs every other row.", "Both equally, and it says so rather than picking one of them.", "Neither, because a rule is named only where the two demands differ."]'::jsonb, 2, 'The ratio per stage there is 2.211629342. On such a row the count sits on the edge of both rules at once, so a small move in either input changes the answer.'),
  ('rotating', 'advanced', 'final', null, 9, 'The last row of the sweep runs to a discharge of 2400.000000 psia. What are the overall ratio, the count and the brake power there?', '["26.086956522, 4 stages and 6085.1118 brake hp.", "26.086956522, 3 stages and 5365.9149 brake hp.", "20.652173913, 4 stages and 5615.9251 brake hp.", "13.043478261, 4 stages and 6085.1118 brake hp."]'::jsonb, 0, 'Power climbs smoothly along that table and the stage count climbs in steps, and each step is a machine, a cooler and a foundation.'),
  ('rotating', 'advanced', 'final', null, 10, 'The sweep also carries a fuel column, running 0.432769057 MMscfd at the lowest discharge pressure and 1.200960144 at the highest. What does that column follow?', '["The overall ratio, because fuel is charged against the pressure the duty asks for.", "The brake horsepower, because the driver is sized on the whole train''s shaft work.", "The stage count, because each machine carries its own driver and its own heat rate.", "The cooling duty, because the fuel gas is drawn off downstream of the last cooler."]'::jsonb, 1, 'More machines means more brake power, and more brake power at one heat rate means more of the stream going up the stack. Fuel compounds with the staging.'),
  ('rotating', 'advanced', 'final', null, 11, 'The cooling column on the same sweep runs from 2.9723 MMBtu per hr to 13.4048. What kind of quantity is that, and who owns it?', '["A correction applied to the brake power, which the driver calculation then removes.", "A bookkeeping figure that closes the energy balance on the stage table.", "The heat the driver rejects, which is why it rises with the brake horsepower.", "A real exchanger duty, and it belongs on somebody''s equipment list."]'::jsonb, 3, 'Read that total beside the brake horsepower total. Moving the approach moves both of them, and the direction that helps one is the direction that hurts the other.'),
  ('rotating', 'advanced', 'final', null, 12, 'The refusal at the twelve-stage cap ends with the clause "from an inlet of 100.0 F". What does that clause add?', '["It identifies which stage of the train the measurement was taken on.", "It gives the suction temperature, which is the only inlet a stage count is ever tested from.", "It says how much room the duty ever had, since the limit of 110.0 F sits barely above it.", "It records the approach the cooler reached, so the cooling can be corrected."]'::jsonb, 2, 'Reporting the limit on its own would leave a reader wondering whether the inlet was the problem. Almost no compression fits in the space between those two figures.'),
  ('rotating', 'advanced', 'final', null, 13, 'Four other faults reach the same function as the twelve-stage cap, and each of them has its own refusal. What does that buy a reader who meets the cap?', '["Certainty that this refusal is the cap and not one of the four, so the diagnosis starts in the right place.", "A guarantee that all four are re-tested at each of the twelve trials, so a late one cannot slip through.", "The four messages, returned alongside the cap''s own, so every possibility is listed.", "A count of how many guards the call passed before it reached the cap."]'::jsonb, 0, 'That is the difference between being told something is wrong and being told what is wrong. The count tried is on the return for the same reason, saying the search ran to its bound.'),
  ('rotating', 'advanced', 'final', null, 14, 'On the discharge-pressure sweep the hottest stage runs 218.0060 degF at the lowest pressure and 290.6346 degF on the 600.000000 psia row. Which row is closest to the stated limit, and by how much?', '["The lowest-pressure row, with 81.9940 degF left.", "The 600.000000 psia row, with 9.3654 degF left.", "The 1500.000000 psia row, with 10.9272 degF left.", "The 2400.000000 psia row, with 35.8243 degF left."]'::jsonb, 1, 'That column is derived on each row as the stated limit less the hottest stage. It is non-negative on all nine rows of the table.'),
  ('rotating', 'advanced', 'final', null, 15, 'The first stage of the SOKU train returns 1461.7913 gas hp and 1510.1150 brake hp. What is the difference between those two figures?', '["The driver losses, which the fuel calculation applies again downstream.", "The cooling duty on that stage, expressed as power rather than as Btu per hr.", "The share of the train total that the second and third stages do not carry.", "The mechanical losses of that one machine, the gearbox, the bearings and the seals."]'::jsonb, 3, 'Every stage on the train carries the same step. Gas horsepower is what the gas receives and brake horsepower is what the coupling has to deliver.'),
  ('rotating', 'advanced', 'final', null, 16, 'Cool a three-stage train back to 90.0000 degF between stages and the stage discharges come out 251.2956, 233.6372 and 233.6372 degF. Why is the first one the hottest?', '["Stage one takes the largest share of the overall ratio, and the two after it split the remainder.", "Stage one is the only stage whose compressibility is evaluated at both ends.", "Stage one runs from the suction of 104.0000 degF, which is warmer than the cooler reaches.", "Stage one is uncooled on its inlet and also uncooled on its outlet, so its heat carries forward."]'::jsonb, 2, 'A single stage starts from the suction and every stage after the first starts from the interstage cooler, so on a cold approach the first stage is the odd one out.'),
  ('rotating', 'advanced', 'final', null, 17, 'Cool the same train back to 180.0000 degF instead and the discharges come out 188.2466, 275.6056, 275.6056, 275.6056 and 275.6056 degF. What has happened to the first stage?', '["It has become the coolest on the train, because the approach now sits well above the suction.", "It has been given a smaller ratio than the four after it, which is how the engine holds the limit.", "It has been cooled on its inlet for the first time, which is what drops it below the others.", "It has stayed where it was, and what changed is only how many stages follow it."]'::jsonb, 0, 'That walk holds the count at 3 through 130.0000 degF and then buys a fourth machine at 150.0000 degF and a fifth at 180.0000 degF.'),
  ('rotating', 'advanced', 'final', null, 18, 'At an intercooler approach of 130.0000 degF the hottest stage on a three-stage train reaches 284.0898 degF. How much room is left under the stated limit?', '["41.1365 degF.", "15.9102 degF.", "48.7044 degF.", "6.7096 degF."]'::jsonb, 1, 'The room shrinks as the approach rises while the count holds, going 48.7044, then 41.1365, then 15.9102 degF across the three-stage rows. Past that the count moves instead.'),
  ('rotating', 'advanced', 'final', null, 19, 'At an approach of 150.0000 degF the count steps to 4 and the hottest stage is 265.9556 degF. What happened to the room under the limit?', '["It stayed at 15.9102 degF, since the limit is what fixed the count in the first place.", "It fell further, to 24.3944 degF, which is what buys the fifth machine at the next step.", "It became meaningless, since the limit is applied to the final discharge rather than to the hottest stage.", "It went back up, to 34.0444 degF, because the extra machine cut the ratio each stage takes."]'::jsonb, 3, 'The count moving is what keeps the discharge inside the limit. What the warmer approach bought was a machine rather than a hotter train.'),
  ('rotating', 'advanced', 'final', null, 20, 'At an approach of 180.0000 degF the totals are 8.6948 MMBtu per hr of cooling and 4572.5633 gas hp. How does that row sit against the three-stage rows below it?', '["It carries less cooling than every three-stage row and more power than any of them.", "It carries more cooling and less power than every three-stage row, which is the trade reversed.", "It carries more cooling than the warmest three-stage row and more power than any of them.", "It carries the same cooling as the coldest three-stage row, which is what five stages buy back."]'::jsonb, 2, 'The warmest three-stage row sits at 8.1149 MMBtu per hr and 4453.3383 hp. The trade only reads cleanly on rows that share a stage count.'),
  ('rotating', 'advanced', 'final', null, 21, 'The Compressor Station Designer ships with an intercooler approach of 110 degF against a suction of 100 degF. What does a studio opened and not touched already sit on?', '["The warm side of the comparison, where the approach is what the later stages start from.", "A refusal, because an approach above the suction is outside what the staging calculation accepts.", "The cold side, since 110 degF is below the temperature any stage will reach.", "A default discharge limit, which the approach then has no effect on."]'::jsonb, 0, 'What sits on that side of the comparison is a stage count, and a stage count is a cooler, a foundation and a machine.'),
  ('rotating', 'advanced', 'final', null, 22, 'The same molar flow occupies 4758.4333 acfm at a suction of 60.000000 psia and 442.2902 acfm at 600.000000 psia. What does a screen do with a rate quoted in MMscfd alone?', '["It converts the rate at the standard base, which is all the screen needs before the ratio.", "Nothing useful, because two duties at one rate can land on opposite sides of the thresholds it uses.", "It applies the thresholds directly, since the acfm thresholds are stated at the standard base.", "It refuses, because the screen takes a volume and a rate cannot be coerced into one."]'::jsonb, 1, 'A rate says nothing about casing size until it has been put at the suction conditions. One low-pressure duty is a large casing and one high-pressure duty at the same rate is a small one.'),
  ('rotating', 'advanced', 'final', null, 23, 'A duty at 43053.4421 acfm with an overall ratio of 2.600000 and 14500.0000 brake hp is screened. Besides its size, what does the second reason line say?', '["That an overall ratio of 2.600000 is too high for a wheel to take in one bite.", "That at that volume the decision goes on footprint and maintenance philosophy.", "That under 200 bhp a packaged gas-engine recip would be the usual answer.", "That over 10,000 bhp is turbine-driven centrifugal territory."]'::jsonb, 3, 'The first reason is that 43053 acfm at a modest ratio is centrifugal territory. Two reasons can point the same way, and it is the first that the branch was decided on.'),
  ('rotating', 'advanced', 'final', null, 24, 'A screening suction at 1000.000000 psia and -150.0000 degF is refused. On what grounds?', '["The temperature is below absolute zero, so no reduced coordinate can be formed at all.", "Ppr at that pressure sits above the validity limit of 30, so the z-factor is refused.", "Tpr 0.848 sits below the DAK validity range of 1.0 to 3.0, so the z-factor would be an extrapolation below the critical temperature.", "The solver failed to converge at that state, which the return reports alongside the refusal."]'::jsonb, 2, 'The screen asks for the compressibility before it asks for the volume, so a suction state outside the correlation is refused by name rather than as a missing volume.'),
  ('rotating', 'advanced', 'final', null, 25, 'A driver at 7600.000000 Btu per hp hr is put against the same train. What does it burn, at what efficiency, and what share of the stream?', '["0.829792706 MMscfd at 33.479389 percent, which is 3.191510 percent of throughput.", "0.829792706 MMscfd at 36.349051 percent, which is 2.939549 percent of throughput.", "0.764282755 MMscfd at 33.479389 percent, which is 3.191510 percent of throughput.", "1.004485907 MMscfd at 27.656887 percent, which is 3.863407 percent of throughput."]'::jsonb, 0, 'The heat rate is the driver''s characteristic, the heating value is a property of the gas being burned, and the brake power came from the staging. A fuel figure quoted without all three cannot be reproduced.'),
  ('rotating', 'advanced', 'final', null, 26, 'Two of the module''s constants come out of one return, the mass flow of a single MMscfd of a gravity-one gas. Which two, and in what order?', '["28.962500 for the molecular weight of air first, and 379.483572 standard cubic feet per lbmol once the first is known.", "379.483572 standard cubic feet per lbmol first, and 28.962500 for the molecular weight of air once the first is known.", "1545.350400 for the gas constant first, and 379.483572 standard cubic feet per lbmol once the first is known.", "459.670000 for the Rankine offset first, and 28.962500 for the molecular weight of air once the first is known."]'::jsonb, 1, 'Each constant is measured out of a return rather than read off a source file, which is what makes the measurement evidence about the engine that ships.'),
  ('rotating', 'advanced', 'final', null, 27, 'One constant is read out of the mass, the head, the power and the efficiency of a single stage. Which is it?', '["2544.433577644024 Btu per horsepower hour.", "1545.350400 ft lbf per lbmol degR.", "0.028279485058 psia per degR.", "33000.000000 ft lbf per minute per horsepower."]'::jsonb, 3, 'It is the definition of a horsepower, and it appears in the engine only as part of the packaging the stage power is expressed in.'),
  ('rotating', 'advanced', 'final', null, 28, 'The Rankine offset is 459.670000 and the molecular weight of air is 28.962500. Where does the compression module get them?', '["It reads both from the gas properties module and keeps no copy of either.", "It carries its own copies, which the gas properties module is checked against.", "It derives both from the standard base, which is why the base can be measured from outside.", "It reads the offset from the gas properties module and keeps its own molecular weight of air."]'::jsonb, 0, 'Importing rather than restating is what keeps the provenance of every downstream number knowable. The gas constant in the same module is settled by exactly that rule.'),
  ('rotating', 'advanced', 'final', null, 29, 'Two pump refusals read "a speed change needs a duty to change" and "a trim needs a duty to trim", and both go on to list what is missing. What do they list?', '["The flow and the head only, since the brake power is then derived from those two by the affinity laws.", "The pump curve and the system curve, which are what together would give a duty to change or to trim.", "The flow, the head and the brake power, at the present speed and at the full diameter respectively.", "The speed ratio and the trim ratio, which are what the two calls were given instead."]'::jsonb, 2, 'A reader has one thing to correct and the job of the message is to name it. A generic refusal is a correct sentence that costs somebody an hour.'),
  ('rotating', 'advanced', 'final', null, 30, 'A viscosity correction is asked at zero speed and again at a negative speed. What comes back each time?', '["A refusal on the zero and a warning on the negative, since a sign can be a typing slip.", "The same refusal both times, that the correction needs a positive pump speed in rpm.", "A refusal naming the viscosity rather than the speed, which is the input the correction is about.", "A NaN both times, because the correction is one of the bare-number functions."]'::jsonb, 1, 'Neither zero nor a negative is a speed a machine turns at, and one rule covers both. The guard is positivity here because a pump speed cannot be negative.'),
  ('rotating', 'advanced', 'final', null, 31, 'Two and a half pumps are asked for in parallel. What does the engine say?', '["That the count is rounded down to two machines and a warning is attached to the returned result.", "That a fractional count is accepted and read as a partially loaded machine.", "That the curve is missing, which is the first input the parallel call reads.", "That parallel operation needs a pump curve and a whole number of machines, at least one."]'::jsonb, 3, 'A count is a number of machines. The message names both halves of what the call needs rather than reporting only the one it noticed first.'),
  ('rotating', 'advanced', 'final', null, 32, 'Where is the compressibility validity window declared, and how does the compression module get it?', '["The separator sizing module in the same package declares it, and the compression module imports those bounds.", "The gas properties module declares it alongside the correlation, and the compression module imports it.", "The compression module declares it itself, which is why it can refuse on it by name.", "The wave''s goldens declare it, and both modules are checked against the published figures."]'::jsonb, 0, 'A restated window drifts, and a package holding two opinions about where a correlation stops cannot say which of them any answer sits inside. It is the same one-owner rule the gas constant is settled by.'),
  ('rotating', 'advanced', 'final', null, 33, 'What does a refusal outside that window carry besides its message?', '["The reduced coordinates alone, since the state the caller typed is already in the message.", "The converged flag, so a reader can see the solver was happy at a state that was still refused.", "The reduced coordinates, the pressure and temperature they were taken at, and which end of the train died.", "The z the correlation would have returned, so the size of the extrapolation can be judged."]'::jsonb, 2, 'The reduced pair is what the window is written in and the pressure and temperature are what the user typed, so reporting both saves working out the pseudo-criticals by hand.'),
  ('rotating', 'advanced', 'final', null, 34, 'A suction at 12 psia and 100 F gives a reduced pressure below where the fit data start. Is it refused?', '["Yes, on exactly the same footing as a state sitting above the reduced pressure limit of 30 the window states.", "No. It is accepted and a note is attached saying the z-factor runs toward the ideal-gas limit.", "No, and nothing at all is reported, because a low reduced pressure is an ordinary state for a machine.", "Yes, but as a warning rather than an error, so the numbers still come back."]'::jsonb, 1, 'A window has two kinds of edge and they are not the same kind: extrapolation into unknown behaviour, and extrapolation toward known behaviour.'),
  ('rotating', 'advanced', 'final', null, 35, 'compression.dischargeTempR is handed a suction temperature that is not a number. What comes back?', '["An object carrying an error naming the suction temperature.", "An Infinity, which is what a non-numeric input propagates to here.", "The value at the standard base, which is the documented fallback.", "NaN, because it is one of the bare-number functions."]'::jsonb, 3, 'It has nowhere to put an error key. A caller has to test for finiteness, and a test asking whether the result equals NaN is always false because a NaN is not equal to anything including itself.'),
  ('rotating', 'advanced', 'final', null, 36, 'One stage moves 53577.2205 lb per hr. Where does that figure enter the calculation?', '["It is what the volume at the flange is divided by to reach a density.", "It is what the ratio per stage is applied to, since mass is what a stage takes a bite of.", "It is what the head per pound is multiplied by to reach a power.", "It is what the compressibility is evaluated at, before the two ends are averaged."]'::jsonb, 2, 'Head is work per pound and power is that head carried by the mass, so a rate has to become a mass flow before any horsepower exists at all.'),
  ('rotating', 'advanced', 'final', null, 37, 'The published field table leaves some fields of each case out of the comparison. Which, and why?', '["The ones the file states as inputs, because they are what the case is.", "The ones that come back bit for bit, because they cannot discriminate anything.", "The ones the engine does not return, because there is nothing to compare them against.", "The ones with no tolerance declared beside them in the file."]'::jsonb, 0, 'Checking a case against its own inputs is a comparison that cannot come out false. What is compared is what the engine produced from those inputs.'),
  ('rotating', 'advanced', 'final', null, 38, 'The operating-region bands sit at 50, 70, 120 and 140 percent of best efficiency flow. What is their standing?', '["Measurable out of the engine by bisection, so a region can be graded once the boundary is known.", "Customary and unsourced in this repository, which puts them among the eight items held for literature.", "Published in this repository, which is why all four boundaries can be quoted to the digit.", "Defaults the caller may override, so they are graded only where a caller states them."]'::jsonb, 1, 'A region, a percentage of best efficiency flow and a preferred flag are all off the graded list because of it. Four boundaries, none of them sourced here.'),
  ('rotating', 'advanced', 'final', null, 39, 'The NPSH margin rule is the larger of 3 ft and 35 percent of required. Both halves of it are measurable out of the engine. Why is the rule still held?', '["Because the two halves change places at a required NPSH the engine does not report.", "Because the margin is returned as a ratio rather than as a rule, so nothing can be measured.", "Because the severities the rule produces are words and a graded field has to be a number.", "Because measuring what the engine does is not the same as sourcing where the rule came from."]'::jsonb, 3, 'The measurement is evidence about the engine that ships. A customary figure stays held until somebody reads a publication against it.'),
  ('rotating', 'advanced', 'final', null, 40, 'The implied water density of the pump packagings is held for literature, yet a power and a pressure conversion are both gradeable. How do those sit together?', '["The packagings are the engine''s own definitions and are measurable, while the handbook figure they approximate is not in this repository.", "The conversions are graded only at a specific gravity of one, where the density cancels out.", "The density is held because it is derived twice, and a derived figure cannot be graded.", "The conversions are graded against the published golden cases rather than against the packagings."]'::jsonb, 0, 'What is held is the comparison to a published water density. What is measurable is what the engine carries, and the two questions are not the same question.'),
  ('rotating', 'advanced', 'final', null, 41, 'The Hydraulic Institute viscosity correction is held, and the digest names a further simplification inside it. What is it?', '["The efficiency factor is taken equal to the flow factor at best efficiency.", "The correlating parameter is evaluated at the shutoff head rather than at the duty.", "The head factor is taken equal to the flow factor at best efficiency.", "The flow factor is inverted in closed form rather than solved, which loses a digit."]'::jsonb, 2, 'The correction is empirical and unsourced in this repository, so no graded value in this course is a corrected flow, head or efficiency.'),
  ('rotating', 'advanced', 'final', null, 42, 'This package has no required-NPSH-against-flow curve anywhere in it. What does that absence force a reader to do?', '["Take the required NPSH from the margin rule, which is the only figure the engine carries.", "Read the vendor curve at the duty flow before treating any suction margin as meaningful.", "Treat the available figure as the margin, since there is nothing to subtract from it.", "Read the required NPSH off the published golden cases, which carry two of them."]'::jsonb, 1, 'Until the required value is read at the flow the machine will actually run at, a suction margin is a subtraction with one side of it missing.');
